-- ---------- SVALOVE SKUPINY ----------

with data(name) as (
  values
    ('Chest'),
    ('Back'),
    ('Legs'),
    ('Shoulders'),
    ('Biceps'),
    ('Triceps'),
    ('Core'),
    ('Forearms'),
    ('Neck'),
    ('Cardio')
)
insert into public.muscle_groups (muscle_group_name)
select name from data;

-- ---------- SVALOVE PODSKUPINY ----------

with data(muscle, sub) as (
  values
    ('Chest', 'Upper Chest'),
    ('Chest', 'Middle Chest'),
    ('Chest', 'Lower Chest'),
    ('Back', 'Lats'),
    ('Back', 'Upper Back'),
    ('Back', 'Traps'),
    ('Back', 'Lower Back'),
    ('Legs', 'Quadriceps'),
    ('Legs', 'Hamstrings'),
    ('Legs', 'Calves'),
    ('Legs', 'Glutes'),
    ('Legs', 'Adductors'),
    ('Legs', 'Abductors'),
    ('Shoulders', 'Front Delts'),
    ('Shoulders', 'Side Delts'),
    ('Shoulders', 'Rear Delts'),
    ('Biceps', 'Biceps'),
    ('Triceps', 'Triceps'),
    ('Core', 'Abs'),
    ('Core', 'Obliques'),
    ('Forearms', 'Forearms'),
    ('Neck', 'Neck'),
    ('Cardio', 'Steady State')
)
insert into public.sub_muscle_groups (muscle_group_id, sub_muscle_name)
select mg.muscle_group_id, d.sub
from data d
join public.muscle_groups mg on mg.muscle_group_name = d.muscle;

