insert into public.exercises (sub_muscle_id, exercise_name, exercise_type, equipment, exercise_icon_url)
select sg.sub_muscle_id, d.name, d.type, d.equipment, d.gif_url
from data d
join public.sub_muscle_groups sg on sg.sub_muscle_name = d.sub
join public.muscle_groups mg
  on mg.muscle_group_id = sg.muscle_group_id
  and mg.muscle_group_name = d.muscle;

